/// A map from key to number, so that no encoding is positional.
impl Serialize for BodyParams {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let mut map = serializer.serialize_map(Some(BodyParamKey::ALL.len()))?;
        for key in BodyParamKey::ALL {
            map.serialize_entry(key.as_str(), &self.get(key))?;
        }
        map.end()
    }
}
